def parse_json(s: str) -> object:
    """
    A recursive descent parser for JSON that handles strings, numbers, booleans, null, arrays, and objects.
    """

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0

        def parse(self):
            self.skip_whitespace()
            if self.pos == len(self.s):
                raise ValueError("Unexpected end of input")
            c = self.s[self.pos]
            if c == '"':
                return self.parse_string()
            elif c.isdigit() or c == '-':
                return self.parse_number()
            elif c == 't' or c == 'f':
                return self.parse_bool()
            elif c == 'n':
                return self.parse_null()
            elif c == '[':
                return self.parse_array()
            elif c == '{':
                return self.parse_object()
            else:
                raise ValueError(f"Unexpected character {c}")

        def parse_string(self):
            self.pos += 1  # skip opening quote
            result = []
            while self.pos < len(self.s):
                c = self.s[self.pos]
                if c == '"':
                    self.pos += 1
                    return ''.join(result)
                elif c == '\\':
                    self.pos += 1
                    escape = self.s[self.pos]
                    if escape in ('"', '\\', '/'):
                        result.append(escape)
                    elif escape == 'b':
                        result.append('\b')
                    elif escape == 'f':
                        result.append('\f')
                    elif escape == 'n':
                        result.append('\n')
                    elif escape == 'r':
                        result.append('\r')
                    elif escape == 't':
                        result.append('\t')
                    else:
                        raise ValueError(f"Invalid escape character: {escape}")
                else:
                    result.append(c)
                self.pos += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.s[self.pos] == '-':
                self.pos += 1
            while self.pos < len(self.s) and self.s[self.pos].isdigit():
                self.pos += 1
            if self.pos < len(self.s) and self.s[self.pos] == '.':
                self.pos += 1
                while self.pos < len(self.s) and self.s[self.pos].isdigit():
                    self.pos += 1
            num_str = self.s[start:self.pos]
            try:
                return int(num_str) if '.' not in num_str else float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")

        def parse_bool(self):
            if self.s.startswith('true', self.pos):
                self.pos += 4
                return True
            elif self.s.startswith('false', self.pos):
                self.pos += 5
                return False
            raise ValueError(f"Invalid boolean at position {self.pos}")

        def parse_null(self):
            if self.s.startswith('null', self.pos):
                self.pos += 4
                return None
            raise ValueError(f"Invalid null at position {self.pos}")

        def parse_array(self):
            self.pos += 1  # skip '['
            self.skip_whitespace()
            result = []
            if self.pos < len(self.s) and self.s[self.pos] == ']':
                self.pos += 1
                return result
            while True:
                result.append(self.parse())
                self.skip_whitespace()
                if self.pos < len(self.s):
                    if self.s[self.pos] == ']':
                        self.pos += 1
                        return result
                    elif self.s[self.pos] == ',':
                        self.pos += 1
                        self.skip_whitespace()
                    else:
                        raise ValueError("Expected ',' or ']' in array")
                else:
                    raise ValueError("Unexpected end of input in array")

        def parse_object(self):
            self.pos += 1  # skip '{'
            self.skip_whitespace()
            result = {}
            if self.pos < len(self.s) and self.s[self.pos] == '}':
                self.pos += 1
                return result
            while True:
                key = self.parse_string()
                self.skip_whitespace()
                if self.pos >= len(self.s) or self.s[self.pos] != ':':
                    raise ValueError("Expected ':' after key in object")
                self.pos += 1  # skip ':'
                value = self.parse()
                result[key] = value
                self.skip_whitespace()
                if self.pos < len(self.s):
                    if self.s[self.pos] == '}':
                        self.pos += 1
                        return result
                    elif self.s[self.pos] == ',':
                        self.pos += 1
                        self.skip_whitespace()
                    else:
                        raise ValueError("Expected ',' or '}' in object")
                else:
                    raise ValueError("Unexpected end of input in object")

        def skip_whitespace(self):
            while self.pos < len(self.s) and self.s[self.pos].isspace():
                self.pos += 1

    parser = Parser(s)
    return parser.parse()

def parse_json(s: str) -> object:
    """
    A state machine approach for parsing JSON that reads tokens iteratively. 
    This method consumes input characters and builds the output object without recursion.
    """

    class StateMachine:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.length = len(s)

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Unexpected end of input")
            c = self.s[self.pos]
            if c == '"':
                return self.parse_string()
            elif c.isdigit() or c == '-':
                return self.parse_number()
            elif c == 't' or c == 'f':
                return self.parse_bool()
            elif c == 'n':
                return self.parse_null()
            elif c == '[':
                return self.parse_array()
            elif c == '{':
                return self.parse_object()
            else:
                raise ValueError(f"Unexpected character {c}")

        def parse_string(self):
            self.pos += 1  # skip opening quote
            result = []
            while self.pos < self.length:
                c = self.s[self.pos]
                if c == '"':
                    self.pos += 1
                    return ''.join(result)
                elif c == '\\':
                    self.pos += 1
                    escape = self.s[self.pos]
                    result.append(self.handle_escape(escape))
                else:
                    result.append(c)
                self.pos += 1
            raise ValueError("Unterminated string")

        def handle_escape(self, escape):
            escape_map = {
                '"': '"', '\\': '\\', '/': '/',
                'b': '\b', 'f': '\f', 'n': '\n',
                'r': '\r', 't': '\t'
            }
            if escape in escape_map:
                self.pos += 1
                return escape_map[escape]
            else:
                raise ValueError(f"Invalid escape character: {escape}")

        def parse_number(self):
            start = self.pos
            if self.s[self.pos] == '-':
                self.pos += 1
            while self.pos < self.length and self.s[self.pos].isdigit():
                self.pos += 1
            if self.pos < self.length and self.s[self.pos] == '.':
                self.pos += 1
                while self.pos < self.length and self.s[self.pos].isdigit():
                    self.pos += 1
            num_str = self.s[start:self.pos]
            return int(num_str) if '.' not in num_str else float(num_str)

        def parse_bool(self):
            if self.s[self.pos:self.pos + 4] == 'true':
                self.pos += 4
                return True
            elif self.s[self.pos:self.pos + 5] == 'false':
                self.pos += 5
                return False
            raise ValueError(f"Invalid boolean at position {self.pos}")

        def parse_null(self):
            if self.s[self.pos:self.pos + 4] == 'null':
                self.pos += 4
                return None
            raise ValueError(f"Invalid null at position {self.pos}")

        def parse_array(self):
            self.pos += 1  # skip '['
            result = []
            self.skip_whitespace()
            if self.pos < self.length and self.s[self.pos] == ']':
                self.pos += 1
                return result
            while True:
                result.append(self.parse())
                self.skip_whitespace()
                if self.pos < self.length:
                    if self.s[self.pos] == ']':
                        self.pos += 1
                        return result
                    elif self.s[self.pos] == ',':
                        self.pos += 1
                        self.skip_whitespace()
                    else:
                        raise ValueError("Expected ',' or ']' in array")

        def parse_object(self):
            self.pos += 1  # skip '{'
            result = {}
            self.skip_whitespace()
            if self.pos < self.length and self.s[self.pos] == '}':
                self.pos += 1
                return result
            while True:
                key = self.parse_string()
                self.skip_whitespace()
                if self.pos >= self.length or self.s[self.pos] != ':':
                    raise ValueError("Expected ':' after key in object")
                self.pos += 1  # skip ':'
                value = self.parse()
                result[key] = value
                self.skip_whitespace()
                if self.pos < self.length:
                    if self.s[self.pos] == '}':
                        self.pos += 1
                        return result
                    elif self.s[self.pos] == ',':
                        self.pos += 1
                        self.skip_whitespace()
                    else:
                        raise ValueError("Expected ',' or '}' in object")

        def skip_whitespace(self):
            while self.pos < self.length and self.s[self.pos].isspace():
                self.pos += 1

    state_machine = StateMachine(s)
    return state_machine.parse()

